module operators;
fn main() -> bool effects [] { let value: i64 = (40 + 2) * 2 / 2 % 43; return value >= 1 && !(value == 0); }

module effects_demo;
fn send(value: string) -> unit effects [network_send] { request network_send(value); return; }
fn main() -> unit effects [network_send] { send("payload"); return; }

module secure flow;
fn relay(value: string flow [secret, tenant:agent_a, purpose:handoff]) -> string flow [secret, tenant:agent_a, purpose:handoff] effects [] authorities [] { return value; }
fn main() -> unit flow [public] effects [network_send] authorities [send_once: network_send] { let payload: string flow [secret, tenant:agent_a, purpose:handoff] = "data"; request network_send(relay(payload)) using send_once flow [secret, tenant:agent_a, purpose:handoff]; return; }

module contextual;
fn echo(flow: i64, authorities: i64) -> i64 effects [] { let using: i64 = flow + authorities; return using; }
fn main() -> i64 effects [] { return echo(20, 22); }
